from decimal import Decimal; from pathlib import Path; from uuid import uuid4; import pytest; from src.extraction import DocumentSource; from src.extraction.base.validation import compute_confidence_score, validate_balance; from src.extraction.extension.service import ExtractionError, ExtractionService
class TestBalanceValidation:
    def setup_method(self): self.service = ExtractionService()
    def test_balance_valid(self): 'AC-extraction.101.1'; extracted = {'opening_balance': '1000.00', 'closing_balance': '1100.00', 'transactions': [{'amount': '200.00', 'direction': 'IN'}, {'amount': '100.00', 'direction': 'OUT'}]}; result = validate_balance(extracted); assert result['balance_valid'] is True; assert result['difference'] == '0.00'
    def test_balance_invalid(self): 'AC-extraction.101.2'; extracted = {'opening_balance': '1000.00', 'closing_balance': '2000.00', 'transactions': [{'amount': '100.00', 'direction': 'IN'}]}; result = validate_balance(extracted); assert result['balance_valid'] is False; assert 'mismatch' in result['notes'].lower()
    def test_balance_tolerance(self): 'AC-extraction.101.3'; extracted = {'opening_balance': '1000.00', 'closing_balance': '1100.005', 'transactions': [{'amount': '100.00', 'direction': 'IN'}]}; result = validate_balance(extracted); assert result['balance_valid'] is True
class TestConfidenceScoring:
    def setup_method(self): self.service = ExtractionService()
    def test_high_confidence(self): 'AC-extraction.102.1'; extracted = {'institution': 'DBS', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1100.00', 'transactions': [{'date': '2025-01-15', 'amount': '100.00', 'direction': 'IN'}]}; validation = {'balance_valid': True, 'difference': '0.00'}; score = compute_confidence_score(extracted, validation); assert score >= 85, f'Expected high confidence, got {score}'
    def test_medium_confidence(self): 'AC-extraction.3.2'; extracted = {'institution': 'DBS', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1105.00', 'transactions': [{'date': '2025-01-15', 'amount': '100.00', 'direction': 'IN'}]}; validation = {'balance_valid': False, 'difference': '5.00'}; score = compute_confidence_score(extracted, validation); assert 60 <= score < 85, f'Expected medium confidence, got {score}'
    def test_low_confidence_empty_transactions(self): 'AC-extraction.3.3 AC-extraction.102.3'; extracted = {'institution': 'DBS', 'period_start': 'invalid-date', 'period_end': '2025-01-31', 'opening_balance': '0', 'closing_balance': '0', 'transactions': []}; validation = {'balance_valid': False, 'difference': '100.00'}; score = compute_confidence_score(extracted, validation); assert score < 60, 'Low-confidence statements should require manual review'
class TestFixtureData:
    @pytest.fixture
    def dbs_fixture(self): return {'success': True, 'institution': 'DBS', 'statement': {'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '100.00', 'closing_balance': '250.00', 'currency': 'SGD', 'balance_validated': True, 'confidence_score': 95}, 'events': [{'date': '2025-01-05', 'description': 'Card payment', 'amount': '50.00', 'direction': 'OUT'}, {'date': '2025-01-10', 'description': 'Salary credit', 'amount': '200.00', 'direction': 'IN'}]}
    @pytest.fixture
    def maribank_fixture(self): return {'success': True, 'institution': 'MariBank', 'statement': {'period_start': '2025-04-01', 'period_end': '2025-04-30', 'opening_balance': '0.00', 'closing_balance': '18.00', 'currency': 'SGD', 'balance_validated': True}, 'events': [{'date': '2025-04-03', 'description': 'Card payment', 'amount': '12.00', 'direction': 'OUT'}, {'date': '2025-04-15', 'description': 'Transfer in', 'amount': '30.00', 'direction': 'IN'}]}
    @pytest.fixture
    def gxs_fixture(self): return {'success': True, 'institution': 'GXS', 'statement': {'period_start': '2025-06-01', 'period_end': '2025-06-30', 'opening_balance': '0.00', 'closing_balance': '0.25', 'currency': 'SGD', 'balance_validated': True}, 'events': [{'date': f'2025-06-{day:02d}', 'description': 'Interest', 'amount': '0.01', 'direction': 'IN'} for day in range(1, 26)]}
    def test_dbs_fixture_structure(self, dbs_fixture): 'AC-extraction.103.1'; assert dbs_fixture['success'] is True; assert dbs_fixture['institution'] == 'DBS'; assert 'statement' in dbs_fixture; assert 'events' in dbs_fixture; assert len(dbs_fixture['events']) > 0
    def test_dbs_balance_reconciliation(self, dbs_fixture): 'AC-extraction.103.2'; stmt = dbs_fixture['statement']; events = dbs_fixture['events']; opening = Decimal(stmt['opening_balance']); closing = Decimal(stmt['closing_balance']); net = sum((Decimal(e['amount']) if e['direction'] == 'IN' else -Decimal(e['amount']) for e in events)); expected_closing = opening + net; diff = abs(closing - expected_closing); assert diff < Decimal('1.00'), f'Balance mismatch: {diff}'
    def test_maribank_fixture_descriptions_carry_no_pii(self, maribank_fixture):
        'AC-extraction.103.3'; from src.observability import detect_pii
        for event in maribank_fixture['events']: desc = event.get('description', ''); assert detect_pii(desc) == [], f'PII leaked into fixture description: {desc!r}'
    def test_gxs_fixture_daily_interest(self, gxs_fixture): 'AC-extraction.103.4'; events = gxs_fixture['events']; interest_events = [e for e in events if 'Interest' in e.get('description', '')]; assert len(interest_events) > 20, 'GXS should have daily interest entries'
    def test_all_fixtures_have_dates(self, dbs_fixture, maribank_fixture, gxs_fixture):
        'AC-extraction.103.5'
        for fixture in [dbs_fixture, maribank_fixture, gxs_fixture]:
            for event in fixture['events']: assert event.get('date'), 'Event missing date'; assert len(event['date']) == 10, f"Invalid date format: {event['date']}"; assert event['date'][4] == '-', f"Invalid date format: {event['date']}"
