class TestMediaPayloadBuilder:
    def setup_method(self): from src.extraction.extension.service import ExtractionService; self.service = ExtractionService()
    def test_pdf_url_uses_zai_image_url_type(self):
        'AC-extraction.105.1'; data = 'https://s3.example.test/bucket/statement.pdf?signature=secret'; payload = self.service._build_media_payload('pdf', 'application/pdf', data); assert payload['type'] == 'image_url'; assert payload['image_url']['url'] == data; 'AC-extraction.105.1'; 'AC-extraction.105.1'; _m1_data = 'data:application/pdf;base64,JVBERi0xLjQ='; _m1_payload = self.service._build_media_payload('pdf', 'application/pdf', _m1_data); assert _m1_payload['type'] == 'file'; assert _m1_payload['file']['filename'] == 'statement.pdf'; assert _m1_payload['file']['file_data'] == _m1_data; 'AC-extraction.105.1'; 'AC-extraction.105.1'; from io import BytesIO; from reportlab.pdfgen import canvas; _m2_buffer = BytesIO(); _m2_pdf = canvas.Canvas(_m2_buffer); _m2_pdf.drawString(72, 720, 'DBS statement fixture'); _m2_pdf.save(); _m2_batches = self.service._render_pdf_pages_as_image_payload_batches(_m2_buffer.getvalue()); assert len(_m2_batches) == 1; assert len(_m2_batches[0]) == 1; assert _m2_batches[0][0]['type'] == 'image_url'; assert _m2_batches[0][0]['image_url']['url'].startswith('data:image/png;base64,'); 'AC-extraction.105.1'; 'AC-extraction.105.1'
        with pytest.raises(ExtractionError, match='No valid file content or accessible URL'): self.service._build_ai_file_input(file_content=None, file_url='http://10.0.0.5/statements/file.pdf?token=secret', file_type='pdf', mime_type='application/pdf', prefer_url=True)
    def test_png_uses_image_url_type(self): 'AC-extraction.105.2'; data = 'data:image/png;base64,iVBORw0KGgo='; payload = self.service._build_media_payload('png', 'image/png', data); assert payload['type'] == 'image_url'; assert 'image_url' in payload; assert payload['image_url']['url'] == data
    def test_jpg_uses_image_url_type(self): 'AC-extraction.105.3'; data = 'data:image/jpeg;base64,/9j/4AAQSkZJRg=='; payload = self.service._build_media_payload('jpg', 'image/jpeg', data); assert payload['type'] == 'image_url'; assert payload['image_url']['url'] == data
    def test_jpeg_uses_image_url_type(self): 'AC-extraction.105.4'; data = 'https://example.com/statement.jpeg'; payload = self.service._build_media_payload('jpeg', 'image/jpeg', data); assert payload['type'] == 'image_url'; assert payload['image_url']['url'] == data
