class TestUnderExtractionPenalty:
    @staticmethod
    def _brokerage_extracted(transactions): return {'institution': 'Futu', 'period_start': '2025-06-01', 'period_end': '2025-06-30', 'opening_balance': '0.00', 'closing_balance': '100.00', 'currency': 'HKD', 'transactions': transactions}
    def test_brokerage_single_txn_penalized(self): 'AC-extraction.115.1'; extracted = self._brokerage_extracted([{'date': '2025-06-15', 'description': 'Aggregate', 'amount': '100.00', 'direction': 'IN', 'currency': 'HKD'}]); balance_result = {'balance_valid': True, 'difference': '0.00'}; unpenalized = compute_confidence_score(extracted, balance_result, is_brokerage=False); penalized = compute_confidence_score(extracted, balance_result, is_brokerage=True); assert penalized < unpenalized, 'Under-capture should lower confidence vs the un-penalized score'; assert penalized <= 60, f'1-txn brokerage should stay in review band, got {penalized}'
    def test_brokerage_sufficient_txns_not_penalized(self): 'AC-extraction.115.2'; txns = [{'date': '2025-06-10', 'description': 'Buy', 'amount': '40.00', 'direction': 'OUT', 'currency': 'HKD'}, {'date': '2025-06-20', 'description': 'Sell', 'amount': '140.00', 'direction': 'IN', 'currency': 'HKD'}]; extracted = self._brokerage_extracted(txns); balance_result = {'balance_valid': True, 'difference': '0.00'}; score = compute_confidence_score(extracted, balance_result, is_brokerage=True); assert score > 60, f'Plausible brokerage parse should not be penalized, got {score}'
    def test_bank_single_txn_not_penalized(self): 'AC-extraction.115.3'; extracted = {'institution': 'DBS', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '0.00', 'closing_balance': '100.00', 'transactions': [{'date': '2025-01-01', 'description': 'A', 'amount': '100.00', 'direction': 'IN'}]}; balance_result = {'balance_valid': True, 'difference': '0.00'}; assert compute_confidence_score(extracted, balance_result, is_brokerage=False) == 85
    def test_default_is_not_brokerage(self): 'AC-extraction.115.4'; extracted = self._brokerage_extracted([{'date': '2025-06-15', 'description': 'Aggregate', 'amount': '100.00', 'direction': 'IN', 'currency': 'HKD'}]); balance_result = {'balance_valid': True, 'difference': '0.00'}; assert compute_confidence_score(extracted, balance_result) == compute_confidence_score(extracted, balance_result, is_brokerage=False)
    def test_effective_count_uses_persisted_not_extracted(self): 'AC-extraction.115.5'; txns = [{'date': '2025-06-10', 'description': 'Buy', 'amount': '40.00', 'direction': 'OUT', 'currency': 'HKD'}, {'date': '2025-06-20', 'description': 'Sell', 'amount': '140.00', 'direction': 'IN', 'currency': 'HKD'}]; extracted = self._brokerage_extracted(txns); balance_result = {'balance_valid': True, 'difference': '0.00'}; not_capped = compute_confidence_score(extracted, balance_result, is_brokerage=True); capped = compute_confidence_score(extracted, balance_result, is_brokerage=True, effective_txn_count=1); assert capped <= 60 < not_capped
